<?php

namespace OGame\Http\Controllers\Api\V1;

use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\ValidationException;
use OGame\Actions\Fortify\CreateNewUser;
use OGame\Exceptions\ApiException;
use OGame\Models\ApiToken;
use OGame\Models\User;

class AuthController extends ApiController
{
    /**
     * Create an account (with its start planets) and return a bearer token.
     *
     * Body: email, password, optional token_name.
     * The player name is generated by the game, like it is for registrations in the web UI.
     * As in the web UI, the very first account on a fresh server becomes the admin.
     *
     * @throws ApiException
     */
    public function register(Request $request, CreateNewUser $creator): JsonResponse
    {
        if (!config('ogamex_api.registration_enabled')) {
            throw new ApiException('registration_disabled', 'Registration through the API is disabled on this server.', 403);
        }

        $input = $this->validated($request->all(), [
            'email' => ['required', 'string', 'email', 'max:255'],
            'password' => ['required', 'string'],
            'token_name' => ['nullable', 'string', 'max:64'],
        ]);

        try {
            // Checks that the e-mail is not used yet and that the password meets the server's rules.
            $user = $creator->create([
                'email' => (string)$input['email'],
                'password' => (string)$input['password'],
            ]);
        } catch (ValidationException $e) {
            throw new ApiException('validation_failed', 'The given data was invalid.', 422, $e->errors());
        }

        return $this->tokenResponse($user, (string)($input['token_name'] ?? 'default'), 201);
    }

    /**
     * Exchange e-mail and password for a new bearer token.
     *
     * @throws ApiException
     */
    public function login(Request $request): JsonResponse
    {
        $input = $this->validated($request->all(), [
            'email' => ['required', 'string', 'email'],
            'password' => ['required', 'string'],
            'token_name' => ['nullable', 'string', 'max:64'],
        ]);

        /** @var User|null $user */
        $user = User::where('email', $input['email'])->first();

        if ($user === null) {
            // Spend the same time as a real password check so response time does not reveal
            // whether an e-mail address has an account.
            Hash::make((string)$input['password']);
            throw new ApiException('invalid_credentials', 'E-mail or password is incorrect.', 401);
        }
        if (!Hash::check((string)$input['password'], $user->password)) {
            throw new ApiException('invalid_credentials', 'E-mail or password is incorrect.', 401);
        }
        if ($user->isBanned()) {
            throw new ApiException('account_banned', 'This account is banned.', 403);
        }

        return $this->tokenResponse($user, (string)($input['token_name'] ?? 'default'), 200);
    }

    /**
     * Revoke the token that was used for this request.
     */
    public function logout(Request $request): JsonResponse
    {
        /** @var ApiToken $token */
        $token = $request->attributes->get('api_token');
        $token->delete();

        return $this->ok(['revoked' => true]);
    }

    private function tokenResponse(User $user, string $tokenName, int $status): JsonResponse
    {
        [$token, $plain] = ApiToken::issue($user, $tokenName, (int)config('ogamex_api.token_ttl_days'));

        return $this->ok([
            'token' => $plain,
            'token_type' => 'Bearer',
            'expires_at' => $token->expires_at?->toIso8601String(),
            'user' => [
                'id' => $user->id,
                'username' => $user->username,
                'email' => $user->email,
            ],
        ], $status);
    }
}
